import{_ as a,o,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Manual de Desarrollador","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/dev-guide/index.md","filePath":"es-ES/dev-guide/index.md","lastUpdated":1785993908000}'),i={name:"es-ES/dev-guide/index.md"};function t(n,e,d,l,c,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="manual-de-desarrollador" tabindex="-1">Manual de Desarrollador <a class="header-anchor" href="#manual-de-desarrollador" aria-label="Permalink to &quot;Manual de Desarrollador&quot;">​</a></h1><p>Lertaro ofrece un SDK de plugins abierto (<code>Lertaro.PluginSdk</code>) que ensamblados de terceros pueden usar como destino para ampliar el comportamiento de búsqueda, añadir acciones de menú contextual, integrarse con otras ventanas y personalizar la interfaz. Este manual documenta esa superficie.</p><ul><li><strong><a href="./architecture.html">Arquitectura</a></strong> — cómo encajan entre sí la App, el Servicio en segundo plano y los plugins.</li><li><strong><a href="./getting-started.html">Primeros pasos</a></strong> — cómo crear la estructura de un proyecto de plugin y cargarlo.</li><li><strong>Referencia del SDK de Plugins</strong>: <ul><li><strong><a href="./sdk/core-search-actions.html">Búsqueda y acciones principales</a></strong> — cómo contribuir resultados de búsqueda y acciones de resultado.</li><li><strong><a href="./sdk/system-adapters.html">Adaptadores de sistema y de diálogo</a></strong> — integración con el Explorador de archivos, diálogos de archivo nativos y otras ventanas en primer plano.</li><li><strong><a href="./sdk/ui-extensions.html">Extensiones de interfaz y vista previa</a></strong> — filtros de la barra lateral, columnas de resultado, vistas previas de archivo, miniaturas, temas y traducciones.</li><li><strong><a href="./sdk/abstractions.html">Abstracciones compartidas</a></strong> — los modelos de solo lectura que reciben los plugins (<code>ISearchResult</code>, <code>IPluginSearchWindow</code>) y el esquema de configuración (<code>IConfigurable</code>).</li><li><strong><a href="./sdk/services.html">Servicios del host</a></strong> — servicios estáticos que el host expone a los plugins (iconos, favoritos, historial, metadatos de archivo, indexación de directorios, configuración por plugin, registro).</li></ul></li><li><strong><a href="./examples.html">Plugins de ejemplo</a></strong> — dos plugins reales, ya distribuidos, como casos de estudio.</li><li><strong><a href="./packaging.html">Empaquetado y despliegue</a></strong> — cómo se detecta y carga una DLL de plugin ya compilada.</li></ul><p>Todas las firmas de interfaz de este documento se han verificado directamente contra el código fuente actual de <code>PluginSdk</code> — si encuentras alguna discrepancia, el código es la fuente autorizada.</p>',4)])])}const m=a(i,[["render",t]]);export{p as __pageData,m as default};
